#!/usr/bin/env bash
# SEVEN row 19 tight case (r19a / r19b): D4 = Q u Roots(Q); no valid 5-hyperplane configuration.  Q2r.pkl regenerated by G777/nq.py.
. "$(dirname "$0")/lib.sh"; S="$FA/seven"; D="$WK/seven"; rm -rf "$D"; mkdir -p "$D"; cp -r "$S/CARRIER" "$S/G777" "$D"/; mkdir "$D/seven"; cp "$S/r19a.py" "$S/r19b.py" "$D/seven/"
cd "$D/G777" && mv Q2r.pkl Q2r_pinned.pkl && $PY -B nq.py > nq.log 2>&1
$PY -B - <<PYEOF
import pickle
a=pickle.load(open('Q2r.pkl','rb')); b=pickle.load(open('Q2r_pinned.pkl','rb'))
ok=(a==b and list(a)==list(b) and len(a)==9450)
print(('PASS' if ok else 'FAIL')+' FULL-A SEVEN_Q2r: nq.py regenerates the 9450 Q -> roots table (Q2r.pkl, same order) = shipped')
PYEOF
want SEVEN_nq "$(grep -c 'Counter({4: 9450})' nq.log)" 1 "nq.py: 9450 distinct size-8 leftovers Q, N_Q = 4 each"
cd "$D/seven"
$PY -B r19a.py > a.out 2>&1; $PY -B r19b.py > b.out 2>&1
want SEVEN_r19a "$(tr '\n' ';' < a.out)" "Q 0 #3-dim root subspaces 24 with 6 roots 12 valid 5-configs 0;Q 1 #3-dim root subspaces 24 with 6 roots 12 valid 5-configs 0;Q 2 #3-dim root subspaces 24 with 6 roots 12 valid 5-configs 0;" "impl A (sympy ranks on G777 Q's): 12 six-root hyperplanes, 0 valid 5-configs for 3 Q's"
want SEVEN_r19b "$(head -3 b.out | tr '\n' ';')" "E8 lines in span(e1..e4): 12;hyperplanes 24 with >=6 roots 12 max 6;valid 5-configs 0;" "impl B (own E8, integer cross products): 12 hyperplanes, 0 valid 5-configs"
